def _box_pa_array(
    cls, value, pa_type: pa.DataType | None = None, copy: bool = False
) -> pa.Array | pa.ChunkedArray:
    """
    Box value into a pyarrow Array or ChunkedArray.

    Parameters
    ----------
    value : Sequence
    pa_type : pa.DataType | None

    Returns
    -------
    pa.Array or pa.ChunkedArray
    """
